import express from "express";
import path from "path";
import fs from "fs";
import { createServer as createViteServer } from "vite";

const LEADS_FILE = path.join(process.cwd(), "leads.json");

// Ensure leads file exists
function ensureLeadsFile() {
  if (!fs.existsSync(LEADS_FILE)) {
    fs.writeFileSync(LEADS_FILE, JSON.stringify([], null, 2), "utf-8");
  }
}

async function startServer() {
  ensureLeadsFile();
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // API Routes FIRST
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok", timestamp: new Date().toISOString() });
  });

  // Save / Record lead silently as soon as step 5 is completed or user reaches final page
  app.post("/api/leads", (req, res) => {
    try {
      const { nome, whatsapp, email, origem, passageiros, prazo, destinoInteresse, tipoViagem, clickedWhatsApp, userAgent, referrer } = req.body;

      if (!nome || !whatsapp) {
        return res.status(400).json({ error: "Nome e WhatsApp são obrigatórios." });
      }

      ensureLeadsFile();
      const raw = fs.readFileSync(LEADS_FILE, "utf-8");
      let leads = [];
      try {
        leads = JSON.parse(raw);
        if (!Array.isArray(leads)) leads = [];
      } catch (e) {
        leads = [];
      }

      const newLead = {
        id: `lead_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
        createdAt: new Date().toISOString(),
        dataRegistroBR: new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" }),
        nome: nome.trim(),
        whatsapp: whatsapp.trim(),
        email: email ? email.trim() : "",
        origem: origem ? origem.trim() : "",
        passageiros: passageiros || "1 pessoa",
        prazo: prazo || "",
        destinoInteresse: destinoInteresse || "Europa",
        tipoViagem: tipoViagem || "Turismo",
        clickedWhatsApp: Boolean(clickedWhatsApp),
        status: clickedWhatsApp ? "converteu_whatsapp" : "lead_sem_whatsapp_remarketing",
        userAgent: userAgent || req.headers["user-agent"] || "",
        ip: req.headers["x-forwarded-for"] || req.socket.remoteAddress || "",
      };

      // Check if lead with same WhatsApp exists recently (update or append)
      const existingIdx = leads.findIndex((l: any) => l.whatsapp.replace(/\D/g, "") === newLead.whatsapp.replace(/\D/g, ""));
      if (existingIdx >= 0) {
        leads[existingIdx] = {
          ...leads[existingIdx],
          ...newLead,
          updatedAt: new Date().toISOString(),
          // preserve clicked status if true
          clickedWhatsApp: leads[existingIdx].clickedWhatsApp || newLead.clickedWhatsApp,
          status: (leads[existingIdx].clickedWhatsApp || newLead.clickedWhatsApp) ? "converteu_whatsapp" : "lead_sem_whatsapp_remarketing"
        };
      } else {
        leads.unshift(newLead);
      }

      fs.writeFileSync(LEADS_FILE, JSON.stringify(leads, null, 2), "utf-8");
      
      return res.status(200).json({ success: true, leadId: newLead.id });
    } catch (err: any) {
      console.error("Error saving lead:", err);
      return res.status(500).json({ error: "Erro ao registrar lead internamente." });
    }
  });

  // Update lead status when they click WhatsApp
  app.patch("/api/leads/clicked-whatsapp", (req, res) => {
    try {
      const { whatsapp } = req.body;
      if (!whatsapp) return res.status(400).json({ error: "WhatsApp missing" });

      ensureLeadsFile();
      const raw = fs.readFileSync(LEADS_FILE, "utf-8");
      let leads = JSON.parse(raw);
      if (Array.isArray(leads)) {
        const clean = whatsapp.replace(/\D/g, "");
        leads = leads.map((l: any) => {
          if (l.whatsapp.replace(/\D/g, "") === clean) {
            return {
              ...l,
              clickedWhatsApp: true,
              status: "converteu_whatsapp",
              whatsappClickedAt: new Date().toISOString()
            };
          }
          return l;
        });
        fs.writeFileSync(LEADS_FILE, JSON.stringify(leads, null, 2), "utf-8");
      }
      return res.status(200).json({ success: true });
    } catch (e) {
      return res.status(500).json({ error: "Failed to update" });
    }
  });

  // Get leads (for remarketing export / CSV download / Facebook Custom Audience list)
  app.get("/api/leads", (req, res) => {
    try {
      ensureLeadsFile();
      const raw = fs.readFileSync(LEADS_FILE, "utf-8");
      const leads = JSON.parse(raw);
      res.json({ count: leads.length, leads });
    } catch (err) {
      res.status(500).json({ error: "Erro ao ler leads." });
    }
  });

  // Export CSV for Meta Ads / Google Ads Custom Audiences
  app.get("/api/leads/export.csv", (req, res) => {
    try {
      ensureLeadsFile();
      const raw = fs.readFileSync(LEADS_FILE, "utf-8");
      const leads = JSON.parse(raw);
      
      let csv = "data_cadastro,nome,primeiro_nome,sobrenome,telefone_whatsapp,origem,passageiros,prazo_viagem,destino,tipo_viagem,status_whatsapp\n";
      for (const l of leads) {
        const names = (l.nome || "").trim().split(" ");
        const firstName = names[0] || "";
        const lastName = names.slice(1).join(" ") || "";
        // Clean phone with +55 country code for Meta Ads matching
        let cleanPhone = (l.whatsapp || "").replace(/\D/g, "");
        if (cleanPhone.length >= 10 && !cleanPhone.startsWith("55")) {
          cleanPhone = "55" + cleanPhone;
        }

        csv += `"${l.dataRegistroBR || l.createdAt}","${l.nome}","${firstName}","${lastName}","+${cleanPhone}","${l.origem || ''}","${l.passageiros || ''}","${l.prazo || ''}","${l.destinoInteresse || ''}","${l.tipoViagem || ''}","${l.clickedWhatsApp ? 'CONVERTEU_WHATSAPP' : 'ABANDONOU_SEM_WHATSAPP_REMARKETING'}"\n`;
      }

      res.setHeader("Content-Type", "text/csv; charset=utf-8");
      res.setHeader("Content-Disposition", "attachment; filename=\"leads_remarketing_europrime.csv\"");
      res.status(200).send("\uFEFF" + csv);
    } catch (err) {
      res.status(500).send("Erro ao exportar CSV");
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
